<?php
declare(strict_types=1);
function auth_payload(PDO $pdo,array $u,?string $token=null):array{$s=load_profile_state($pdo,(int)$u['id']);$p=['user'=>public_user($u),'profile'=>build_user_profile($u,$s,$pdo)];if($token!==null){$p['token']=$token;$p['tokenType']='Bearer';}return$p;}
function handle_auth_route(string $method,string $path):bool{if($path!=='/auth'&&strpos($path,'/auth/')!==0)return false;if($path==='/auth/register'){if($method!=='POST')method_not_allowed(['POST']);auth_register();return true;}if($path==='/auth/login'){if($method!=='POST')method_not_allowed(['POST']);auth_login();return true;}if($path==='/auth/logout'){if($method!=='POST')method_not_allowed(['POST']);auth_logout();return true;}if($path==='/auth/me'){if($method!=='GET')method_not_allowed(['GET']);auth_me();return true;}if($path==='/auth/change-password'){if($method!=='POST')method_not_allowed(['POST']);auth_change_password();return true;}if($path==='/auth/forgot-password'){if($method!=='POST')method_not_allowed(['POST']);auth_forgot_password();return true;}if($path==='/auth/reset-password'){if($method!=='POST')method_not_allowed(['POST']);auth_reset_password();return true;}error_response('NOT_FOUND','مسیر احراز هویت پیدا نشد.',404);return true;}
function auth_register():void{$pdo=Database::pdo();enforce_rate_limit($pdo,'auth-register',(int)app_config('rate_limits.auth_max_attempts',10),(int)app_config('rate_limits.auth_window_seconds',900));$d=read_json_body();reject_unknown_keys($d,['email','password','name','role'],'ثبت‌نام');$email=require_email($d);$pass=require_password($d);$name=optional_string($d,'name',120,'کاربر آیکامپتنسی')?:'کاربر آیکامپتنسی';$role=optional_string($d,'role',120,'متقاضی ارزیابی')?:'متقاضی ارزیابی';try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO users (email,password_hash,name,role,status,created_at,updated_at) VALUES (?,?,?,?,"active",NOW(),NOW())')->execute([$email,password_hash($pass,PASSWORD_DEFAULT),$name,$role]);$uid=(int)$pdo->lastInsertId();create_initial_profile($pdo,$uid);$token=issue_token($pdo,$uid);$u=fetch_user_by_id($pdo,$uid);$pdo->commit();success_response(auth_payload($pdo,$u,$token),201);}catch(PDOException$e){if($pdo->inTransaction())$pdo->rollBack();if($e->getCode()==='23000')error_response('EMAIL_EXISTS','این ایمیل قبلاً ثبت شده است.',409);throw$e;}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
function auth_login():void{$pdo=Database::pdo();$d=read_json_body();reject_unknown_keys($d,['email','password'],'ورود');$email=require_email($d);$pass=(string)($d['password']??'');$rk='auth-login:'.sha1($email.':'.client_ip());if(!is_within_rate_limit($pdo,$rk,(int)app_config('rate_limits.auth_max_attempts',10),(int)app_config('rate_limits.auth_window_seconds',900)))error_response('RATE_LIMITED','تعداد تلاش‌های ورود زیاد است. لطفاً کمی بعد دوباره تلاش کنید.',429);$st=$pdo->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if(!$u||!password_verify($pass,$u['password_hash']))error_response('INVALID_CREDENTIALS','ایمیل یا رمز عبور اشتباه است.',401);if($u['status']!=='active')error_response('ACCOUNT_SUSPENDED','حساب کاربری شما فعال نیست.',403);rate_limit_clear($pdo,$rk);$token=issue_token($pdo,(int)$u['id']);$pdo->prepare('UPDATE users SET last_login_at=NOW(),updated_at=NOW() WHERE id=?')->execute([(int)$u['id']]);$u=fetch_user_by_id($pdo,(int)$u['id']);success_response(auth_payload($pdo,$u,$token));}
function auth_logout():void{$pdo=Database::pdo();require_auth();revoke_current_token($pdo);success_response(['message'=>'خروج با موفقیت انجام شد.']);}
function auth_me():void{$pdo=Database::pdo();$a=require_auth();$u=fetch_user_by_id($pdo,(int)$a['user']['id']);success_response(auth_payload($pdo,$u));}
function auth_change_password():void{$pdo=Database::pdo();$a=require_auth();$d=read_json_body();reject_unknown_keys($d,['currentPassword','current_password','newPassword','new_password'],'تغییر رمز');$current=(string)($d['currentPassword']??$d['current_password']??'');$key=isset($d['newPassword'])?'newPassword':'new_password';$new=require_password($d,$key);$u=fetch_user_by_id($pdo,(int)$a['user']['id']);if(!$u||!password_verify($current,$u['password_hash']))error_response('INVALID_CURRENT_PASSWORD','رمز عبور فعلی اشتباه است.',422);$pdo->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),(int)$u['id']]);$pdo->prepare('DELETE FROM auth_tokens WHERE user_id=? AND id<>?')->execute([(int)$u['id'],(int)$a['token']['id']]);success_response(['message'=>'رمز عبور با موفقیت تغییر کرد.']);}
function auth_forgot_password():void{$pdo=Database::pdo();enforce_rate_limit($pdo,'auth-forgot',(int)app_config('rate_limits.auth_max_attempts',10),(int)app_config('rate_limits.auth_window_seconds',900));$d=read_json_body();reject_unknown_keys($d,['email'],'فراموشی رمز');$email=require_email($d);$st=$pdo->prepare('SELECT * FROM users WHERE email=? AND status="active" LIMIT 1');$st->execute([$email]);$u=$st->fetch();$debug=null;if($u){$raw=bin2hex(random_bytes(32));$exp=date('Y-m-d H:i:s',time()+((int)app_config('app.password_reset_ttl_minutes',30)*60));$pdo->prepare('INSERT INTO password_resets (email,token_hash,expires_at,created_at) VALUES (?,?,?,NOW())')->execute([$email,token_hash($raw),$exp]);$url=rtrim((string)app_config('app.password_reset_url',''),'/');$from=(string)app_config('app.mail_from','');if($url!==''&&$from!==''){@mail($email,'بازیابی رمز عبور آیکامپتنسی',"برای تغییر رمز عبور روی لینک زیر کلیک کنید:\n".$url.'?email='.rawurlencode($email).'&token='.rawurlencode($raw),'From: '.$from);}if((bool)app_config('app.debug_return_reset_token',false))$debug=$raw;}$res=['message'=>'اگر این ایمیل در سیستم وجود داشته باشد، راهنمای بازیابی ارسال می‌شود.'];if($debug!==null)$res['debugResetToken']=$debug;success_response($res);}
function auth_reset_password():void{$pdo=Database::pdo();$d=read_json_body();reject_unknown_keys($d,['email','token','newPassword','new_password'],'بازنشانی رمز');$email=require_email($d);$token=require_string($d,'token',200);$key=isset($d['newPassword'])?'newPassword':'new_password';$new=require_password($d,$key);$pdo->beginTransaction();try{$st=$pdo->prepare('SELECT * FROM password_resets WHERE email=? AND token_hash=? AND used_at IS NULL AND expires_at>NOW() ORDER BY id DESC LIMIT 1 FOR UPDATE');$st->execute([$email,token_hash($token)]);$r=$st->fetch();if(!$r){$pdo->rollBack();error_response('INVALID_RESET_TOKEN','لینک بازیابی نامعتبر یا منقضی شده است.',422);}$pdo->prepare('UPDATE users SET password_hash=?,updated_at=NOW() WHERE email=?')->execute([password_hash($new,PASSWORD_DEFAULT),$email]);$pdo->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([(int)$r['id']]);$pdo->prepare('DELETE t FROM auth_tokens t INNER JOIN users u ON u.id=t.user_id WHERE u.email=?')->execute([$email]);$pdo->commit();success_response(['message'=>'رمز عبور جدید با موفقیت ثبت شد.']);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
